//! References and disclosure policy for message prose.

use threadlane_core::ids::{DecisionId, TaskId};

/// The destinations that prose may activate.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Reference<'a> {
    /// A task in the current space.
    Task(TaskId),
    /// A decision in the current space.
    Decision(DecisionId),
    /// An HTTP or HTTPS URL.
    Web(&'a str),
}

impl<'a> Reference<'a> {
    /// Resolves a link generated by the desktop or a browser URL.
    #[must_use]
    pub fn from_link(url: &'a str) -> Option<Self> {
        if let Some(id) = url.strip_prefix("threadlane:") {
            return match id.as_bytes().first()? {
                b'T' => TaskId::parse(id).map(Self::Task),
                b'D' => DecisionId::parse(id).map(Self::Decision),
                _ => None,
            };
        }
        (url.starts_with("https://") || url.starts_with("http://")).then_some(Self::Web(url))
    }
}

/// One slice of the original Markdown source.
#[derive(Debug, PartialEq, Eq)]
pub enum Segment<'a> {
    /// Ordinary Markdown, including any existing link syntax.
    Text(&'a str),
    /// Code that must be left intact.
    Code(&'a str),
    /// An implicit link and its original text.
    Link(&'a str, Reference<'a>),
    /// A literal opening angle bracket outside code.
    Angle,
    /// An image marker rendered literally, to keep prose local.
    ImageMarker,
}

/// Finds implicit references without rewriting code, explicit links or URLs.
#[must_use]
pub fn segments(text: &str) -> Vec<Segment<'_>> {
    let mut result = Vec::new();
    let mut end = 0;
    let mut plain = 0;
    while end < text.len() {
        let start = end;
        let rest = &text[start..];
        let Some(ch) = rest.chars().next() else { break };
        end += ch.len_utf8();
        let special = if let Some(len) = code_length(text, start, ch) {
            end = start + len;
            Some(Segment::Code(&text[start..end]))
        } else if ch == '!' && rest.starts_with("![") {
            Some(Segment::ImageMarker)
        } else if ch == '['
            && let Some(len) = explicit_link(rest)
        {
            end = start + len;
            // Keep the existing link intact while escaping any HTML in its label.
            Some(Segment::Text(&text[start..end]))
        } else if ch == '<'
            && let Some(close) = rest.find('>')
            && matches!(Reference::from_link(&rest[1..close]), Some(Reference::Web(url)) if !url.contains(char::is_whitespace))
        {
            end = start + close + 1;
            Some(Segment::Link(
                &text[start..end],
                Reference::Web(&rest[1..close]),
            ))
        } else if ch == '<' {
            Some(Segment::Angle)
        } else if boundary(text[..start].chars().next_back()) {
            if let Some(Reference::Web(_)) = Reference::from_link(rest) {
                let url = rest
                    .split(|c: char| c.is_whitespace() || matches!(c, '<' | '>' | '`'))
                    .next()
                    .unwrap_or(rest)
                    .trim_end_matches(['.', ',', ';', '!', '?', ')', ']']);
                end = start + url.len();
                Some(Segment::Link(url, Reference::Web(url)))
            } else if matches!(ch, 'T' | 'D') && rest.as_bytes().get(1) == Some(&b'-') {
                let digits = rest[2..].bytes().take_while(u8::is_ascii_digit).count();
                let id = &rest[..2 + digits];
                if digits >= 4 && boundary(rest[id.len()..].chars().next()) {
                    end = start + id.len();
                    TaskId::parse(id)
                        .map(Reference::Task)
                        .or_else(|| DecisionId::parse(id).map(Reference::Decision))
                        .map(|reference| Segment::Link(id, reference))
                } else {
                    None
                }
            } else {
                None
            }
        } else {
            None
        };
        if let Some(segment) = special {
            if plain < start {
                result.push(Segment::Text(&text[plain..start]));
            }
            result.push(segment);
            plain = end;
        }
    }
    if plain < text.len() {
        result.push(Segment::Text(&text[plain..]));
    }
    result
}

fn boundary(ch: Option<char>) -> bool {
    ch.is_none_or(|c| !c.is_alphanumeric() && !matches!(c, '_' | '-'))
}

fn explicit_link(rest: &str) -> Option<usize> {
    let label_end = rest.find(']')? + 1;
    let tail = &rest[label_end..];
    let closing = match tail.chars().next()? {
        '(' => ')',
        '[' => ']',
        _ => return None,
    };
    Some(label_end + tail.find(closing)? + 1)
}

fn code_length(text: &str, start: usize, marker: char) -> Option<usize> {
    let rest = &text[start..];
    let begins_line = start == 0 || text.as_bytes().get(start - 1) == Some(&b'\n');
    if begins_line && (rest.starts_with("    ") || rest.starts_with('\t')) {
        return Some(rest.find('\n').unwrap_or(rest.len()));
    }
    if !matches!(marker, '`' | '~')
        || text[..start].ends_with(marker)
        || text[..start].ends_with('\\')
    {
        return None;
    }
    let count = rest
        .bytes()
        .take_while(|byte| *byte == marker as u8)
        .count();
    if count >= 3
        && text[..start]
            .rsplit('\n')
            .next()
            .unwrap_or_default()
            .trim_matches([' ', '\t', '>'])
            .is_empty()
        && (marker == '~'
            || !rest[count..]
                .lines()
                .next()
                .unwrap_or_default()
                .contains('`'))
    {
        let mut len = 0;
        for line in rest.split_inclusive('\n') {
            let candidate = line.trim_start_matches([' ', '\t', '>']);
            let fence = candidate
                .bytes()
                .take_while(|byte| *byte == marker as u8)
                .count();
            if len > 0 && fence >= count && candidate[fence..].trim().is_empty() {
                return Some(len + line.len());
            }
            len += line.len();
        }
        return Some(rest.len());
    }
    if marker == '`' {
        let body = &rest[count..];
        let paragraph_len = body
            .split_inclusive('\n')
            .enumerate()
            .take_while(|(index, line)| *index == 0 || !line.trim().is_empty())
            .map(|(_, line)| line.len())
            .sum();
        for (at, _) in body[..paragraph_len].match_indices(marker) {
            let at = at + count;
            if rest[..at].ends_with(marker) {
                continue;
            }
            let closing = rest[at..]
                .bytes()
                .take_while(|byte| *byte == marker as u8)
                .count();
            if closing == count {
                return Some(at + closing);
            }
        }
    }
    None
}

/// Prepares source for the Markdown view, keeping HTML as literal text.
#[must_use]
pub fn markdown_source(text: &str) -> String {
    markdown_source_with_time(text, None)
}

/// Prepares source for the Markdown view, keeping HTML as literal text and
/// optionally humanizing bare ISO-8601 UTC timestamps and full 40-char git SHAs
/// outside code and URLs.
#[must_use]
pub fn markdown_source_with_time(text: &str, when: Option<&crate::When>) -> String {
    let mut source = String::with_capacity(text.len());
    for segment in segments(text) {
        match segment {
            Segment::Text(text) => {
                let humanized = humanize_plain_text(text, when);
                source.push_str(&humanized.replace('<', "&lt;").replace("![", "&#33;["));
            }
            Segment::ImageMarker => source.push_str("&#33;"),
            Segment::Angle => source.push_str("&lt;"),
            Segment::Code(code) | Segment::Link(code, Reference::Web(_)) => source.push_str(code),
            Segment::Link(label, _) => {
                source.push('[');
                source.push_str(label);
                source.push_str("](threadlane:");
                source.push_str(label);
                source.push(')');
            }
        }
    }
    source
}

/// Rewrites standalone ISO-8601 UTC timestamps (`2026-11-18T17:19:47Z`) to
/// local moments (when `when` is provided) and bare 40-char lowercase hex git
/// SHAs to short inline code spans (`` `9667947` ``).
fn humanize_plain_text(text: &str, when: Option<&crate::When>) -> String {
    let mut out = String::with_capacity(text.len());
    let mut pos = 0;
    let mut plain = 0;
    while pos < text.len() {
        let start = pos;
        let rest = &text[start..];
        let Some(ch) = rest.chars().next() else {
            break;
        };
        pos += ch.len_utf8();
        // Preserve explicit Markdown links (`[label](dest)` / `[label][ref]`)
        // verbatim so link destinations are never rewritten.
        if ch == '['
            && let Some(len) = explicit_link(rest)
        {
            pos = start + len;
            continue;
        }
        if !boundary(text[..start].chars().next_back()) {
            continue;
        }
        // Check for ISO-8601 UTC timestamp: YYYY-MM-DDTHH:MM:SS[.fff]Z
        if let Some(when) = when
            && ch.is_ascii_digit()
            && rest.len() >= 20
            && rest.as_bytes().get(4) == Some(&b'-')
            && rest.as_bytes().get(10) == Some(&b'T')
            && let Some(z_offset) = rest.find('Z')
            && (19..=30).contains(&z_offset)
        {
            let candidate = &rest[..=z_offset];
            if boundary(rest[candidate.len()..].chars().next())
                && let Some(ts) = crate::clock::parse_iso_utc(candidate)
            {
                out.push_str(&text[plain..start]);
                out.push_str(&when.moment(ts));
                pos = start + candidate.len();
                plain = pos;
                continue;
            }
        }
        // Check for bare 40-char lowercase hex commit SHA (must contain at least one a-f
        // and one digit so plain 40-digit numbers aren't touched).
        if (ch.is_ascii_digit() || matches!(ch, 'a'..='f')) && rest.len() >= 40 {
            let hex_len = rest
                .bytes()
                .take_while(|b| b.is_ascii_digit() || matches!(b, b'a'..=b'f'))
                .count();
            if hex_len == 40 && boundary(rest[40..].chars().next()) {
                let sha = &rest[..40];
                let has_alpha = sha.bytes().any(|b| matches!(b, b'a'..=b'f'));
                let has_digit = sha.bytes().any(|b| b.is_ascii_digit());
                if has_alpha && has_digit {
                    out.push_str(&text[plain..start]);
                    out.push('`');
                    out.push_str(&sha[..7]);
                    out.push('`');
                    pos = start + 40;
                    plain = pos;
                }
            }
        }
    }
    if plain < text.len() {
        out.push_str(&text[plain..]);
    }
    out
}

/// A rendered prose disclosure. The kit reports overflow after layout.
#[derive(Debug, Clone, Copy)]
pub enum ProseLimit {
    /// Always display the full text.
    Full,
    /// Home's compact result preview.
    Result,
    /// An older conversation message.
    Message,
    /// The body of a long decision question.
    Question,
}

impl ProseLimit {
    /// A line cap and the corresponding disclosure label, when appropriate.
    #[must_use]
    pub fn disclosure(
        self,
        expanded: bool,
        overflows: bool,
    ) -> (Option<usize>, Option<&'static str>) {
        let (lines, show, hide) = match self {
            Self::Full => return (None, None),
            Self::Result => (3, "Show", "Hide"),
            Self::Message => (40, "Show more", "Show less"),
            Self::Question => (6, "Show more", "Show less"),
        };
        if expanded {
            (None, Some(hide))
        } else {
            (Some(lines), overflows.then_some(show))
        }
    }
}
